#include <vector>
using namespace std;
struct ListNode {
    long long val;
    ListNode *next;
    ListNode(long long x) : val(x), next(NULL) {}
};
int main() {
    int n; 
    if (!(cin >> n) || n == 0) { cout << "\n"; return 0; }
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    ListNode* head = new ListNode(a[0]);
    ListNode* curr = head;
    for (int i = 1; i < n; i++) {
        curr->next = new ListNode(a[i]);
        curr = curr->next;
    }
    // Write your reversal logic here
    // Then print the values
    return 0;
}

