import java.util.*;
import java.io.*;
class ListNode {
    long val;
    ListNode next;
    ListNode(long x) { val = x; next = null; }
}
public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String nStr = br.readLine();
        if (nStr == null || nStr.trim().isEmpty()) return;
        int n = Integer.parseInt(nStr.trim());
        if (n == 0) { System.out.println(); return; }
        StringTokenizer st = new StringTokenizer(br.readLine());
        ListNode head = new ListNode(Long.parseLong(st.nextToken()));
        ListNode curr = head;
        for (int i = 1; i < n; i++) {
            curr.next = new ListNode(Long.parseLong(st.nextToken()));
            curr = curr.next;
        }
        // Write your reversal logic here
        // Then print the values
    }
}
